from runtime import build, read

def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    raise NotImplementedError

def load_payload(path):
    return read(path)

def build_component(root, contract):
    return build(root, contract, transform)

def assess_selection(request, roots, selected):
    'Accept the public request, a list of root request rows with original intervals, and selected as a mapping from package ID to version list. Omitted packages are unselected and the mapping may be empty. Return None if this complete choice is invalid. Otherwise return a dict with active_dependencies, prior_deltas, and score in the public formats. Apply feature activity, required closure, peer membership, half-open intervals, valid offered selections, and the unchanged prior and freshness rules.\n\nLocal check: Give A only version [1,0,0], with a peer dependency on B enabled by turbo, and B only version [1,0,0]. With turbo enabled and only A rooted, assert that A alone is invalid and that adding B to the selected mapping is also invalid. With B independently rooted, assert the same two-version selection is valid and retains its peer row.'
    raise NotImplementedError

def select_versions(request, roots, assess):
    'Accept the public request, any subset of the original root request rows, and a callable assess(roots, selected) that returns the exact complete-choice evaluation dict or None. Return a dict with feasible_count, selected, and evaluation. Count all distinct feasible complete assignments exactly once. selected is a mapping of IDs to versions for any selection with minimum changes and then maximum freshness, and evaluation is the corresponding assessor result. For zero feasible assignments return selected as {} and evaluation as None. The interface permits pruning and leaves the exact search strategy open.\n\nLocal check: Give a single rooted package A with offered versions [1,0,0], [2,0,0], and [3,0,0], and an unconstrained interval. Use a local assessor fixture that accepts those three nonempty single-package selections. It assigns changes 0 to version 1 and changes 1 to the others with normal freshness. Assert that feasible_count is 3 and selected is version 1 despite the higher freshness alternatives.'
    raise NotImplementedError

