def select_versions(request, roots, assess):
    """Enumerate every distinct feasible complete assignment exactly once and
    return the one minimizing changes and then maximizing freshness.

    request: public request with config (roots, features, prior) and catalog.
    roots: any subset of the original root request rows (with original intervals).
    assess: callable assess(roots, selected) -> evaluation dict or None.
    """
    config = request["config"]
    features = set(config.get("features", []))
    catalog = request["catalog"]

    packages = [c["package"] for c in catalog]
    versions_by_pkg = {}
    deps_by_version = {}
    for c in catalog:
        pkg = c["package"]
        vs = []
        for entry in c["versions"]:
            v = tuple(entry["version"])
            vs.append(v)
            deps_by_version[(pkg, v)] = entry["deps"]
        versions_by_pkg[pkg] = vs

    root_pkgs = set(r["package"] for r in roots)
    root_intervals = {r["package"]: (r["min"], r["max"]) for r in roots}

    def is_active(dep):
        return dep["kind"] == "required" and (
            dep["feature"] is None or dep["feature"] in features
        )

    def req_targets(pkg, v):
        return [d["package"] for d in deps_by_version[(pkg, v)] if is_active(d)]

    # Static over-approximation of the required closure: an edge p -> q exists
    # when some offered version of p has an active required dependency on q.
    graph = {p: set() for p in packages}
    for p in packages:
        for v in versions_by_pkg[p]:
            for t in req_targets(p, v):
                graph[p].add(t)
    reachable = set()
    stack = list(root_pkgs)
    while stack:
        p = stack.pop()
        if p in reachable:
            continue
        reachable.add(p)
        for t in graph[p]:
            if t not in reachable:
                stack.append(t)

    def in_interval(v, mn, mx):
        if mn is not None and tuple(mn) > v:
            return False
        if mx is not None and v >= tuple(mx):
            return False
        return True

    feasible_count = 0
    best = None  # (changes, -freshness, selected_dict, evaluation)

    selected = {}  # pkg -> version tuple, or None for unselected

    def dfs(i, must):
        nonlocal feasible_count, best
        if i == len(packages):
            chosen = {p: list(v) for p, v in selected.items() if v is not None}
            evaluation = assess(roots, chosen)
            if evaluation is not None:
                feasible_count += 1
                score = evaluation["score"]
                key = (score["changes"], -score["freshness"])
                if best is None or key < best[0]:
                    best = (key, chosen, evaluation)
            return

        pkg = packages[i]
        if pkg in must:
            for v in versions_by_pkg[pkg]:
                if pkg in root_intervals:
                    mn, mx = root_intervals[pkg]
                    if not in_interval(v, mn, mx):
                        continue
                targets = req_targets(pkg, v)
                conflict = any(
                    t in selected and selected[t] is None for t in targets
                )
                if conflict:
                    continue
                selected[pkg] = v
                dfs(i + 1, must | set(targets))
                del selected[pkg]
        else:
            # Leave unselected.
            selected[pkg] = None
            dfs(i + 1, must)
            del selected[pkg]
            # Select only if it can possibly belong to the required closure.
            if pkg in reachable:
                for v in versions_by_pkg[pkg]:
                    if pkg in root_intervals:
                        mn, mx = root_intervals[pkg]
                        if not in_interval(v, mn, mx):
                            continue
                    targets = req_targets(pkg, v)
                    conflict = any(
                        t in selected and selected[t] is None for t in targets
                    )
                    if conflict:
                        continue
                    selected[pkg] = v
                    dfs(i + 1, must | set(targets))
                    del selected[pkg]

    dfs(0, set(root_pkgs))

    if feasible_count == 0:
        return {"feasible_count": 0, "selected": {}, "evaluation": None}

    _, chosen, evaluation = best
    return {
        "feasible_count": feasible_count,
        "selected": chosen,
        "evaluation": evaluation,
    }

