import unittest
import sys
sys.path.insert(0, '/workspace')
from packages.analysis.global_selection import select_versions

def make_request(versions, prior=None):
    return {
        "config": {"roots": [{"package": "A", "min": None, "max": None}],
                   "features": [], "prior": prior or {}},
        "catalog": [{"package": "A", "versions": [
            {"version": v, "deps": []} for v in versions
        ]}],
    }

class TestGlobalSelection(unittest.TestCase):
    def test_single_package_three_versions(self):
        req = make_request([[1,0,0],[2,0,0],[3,0,0]])
        roots = req["config"]["roots"]
        def assess(roots, selected):
            v = selected["A"]
            changes = 0 if v == [1,0,0] else 1
            freshness = 100*v[0] + 10*v[1] + v[2]
            return {"active_dependencies": [], "prior_deltas": [],
                    "score": {"changes": changes, "freshness": freshness}}
        res = select_versions(req, roots, assess)
        self.assertEqual(res["feasible_count"], 3)
        self.assertEqual(res["selected"], {"A": [1,0,0]})
        self.assertEqual(res["evaluation"]["score"]["changes"], 0)

    def test_zero_feasible(self):
        req = make_request([[1,0,0]])
        roots = req["config"]["roots"]
        def assess(roots, selected):
            return None
        res = select_versions(req, roots, assess)
        self.assertEqual(res["feasible_count"], 0)
        self.assertEqual(res["selected"], {})
        self.assertIsNone(res["evaluation"])

    def test_empty_roots(self):
        req = make_request([[1,0,0]])
        def assess(roots, selected):
            return {"active_dependencies": [], "prior_deltas": [],
                    "score": {"changes": 0, "freshness": 0}}
        res = select_versions(req, [], assess)
        self.assertEqual(res["feasible_count"], 1)
        self.assertEqual(res["selected"], {})

if __name__ == "__main__":
    unittest.main()
