{"packages/analysis/selection_constraints.py": """"Feature-gated package selection constraint evaluation.

assess_selection(request, roots, selected) validates a complete package
selection against the synthetic dependency format described in SPEC.md and
returns the public evaluation dict, or None when the choice is invalid.
"""


def _version_key(v):
    return tuple(v)


def _in_interval(version, min_v, max_v):
    if min_v is not None and _version_key(version) < _version_key(min_v):
        return False
    if max_v is not None and _version_key(version) >= _version_key(max_v):
        return False
    return True


def _active(dep, features):
    return dep.get("feature") is None or dep.get("feature") in features


def assess_selection(request, roots, selected):
    config = request["config"]
    features = set(config.get("features", []))
    prior = config.get("prior", {})

    catalog = {}
    for entry in request["catalog"]:
        versions = {}
        for v in entry["versions"]:
            versions[tuple(v["version"])] = v
        catalog[entry["package"]] = versions

    # Validate selected mapping: every selected package must exist in the
    # catalog and its version must be an offered version.
    for pkg, version in selected.items():
        if pkg not in catalog:
            return None
        if tuple(version) not in catalog[pkg]:
            return None

    # Every root must be selected within its interval.
    for root in roots:
        pkg = root["package"]
        if pkg not in selected:
            return None
        if not _in_interval(selected[pkg], root.get("min"), root.get("max")):
            return None

    # Compute the required closure starting from roots.
    closure = set()
    stack = [root["package"] for root in roots]
    while stack:
        pkg = stack.pop()
        if pkg in closure:
            continue
        closure.add(pkg)
        version = selected[pkg]
        entry = catalog[pkg][tuple(version)]
        for dep in entry["deps"]:
            if dep["kind"] == "required" and _active(dep, features):
                target = dep["package"]
                if target not in selected:
                    return None
                if not _in_interval(selected[target], dep.get("min"), dep.get("max")):
                    return None
                if target not in closure:
                    stack.append(target)

    # No package outside the required closure may be selected.
    for pkg in selected:
        if pkg not in closure:
            return None

    # Peer dependencies: target must already be in the required closure and
    # satisfy the peer interval.
    active_dependencies = []
    for pkg in closure:
        version = selected[pkg]
        entry = catalog[pkg][tuple(version)]
        for dep in entry["deps"]:
            if not _active(dep, features):
                continue
            target = dep["package"]
            if dep["kind"] == "peer":
                if target not in closure:
                    return None
                if not _in_interval(selected[target], dep.get("min"), dep.get("max")):
                    return None
            active_dependencies.append({
                "source": pkg,
                "target": target,
                "kind": dep["kind"],
                "feature": dep.get("feature"),
            })

    # prior_deltas: union of prior and selected keys where they differ.
    prior_deltas = []
    all_keys = set(prior) | set(selected)
    for pkg in all_keys:
        p = prior.get(pkg)
        s = selected.get(pkg)
        if p != s:
            prior_deltas.append({
                "package": pkg,
                "prior": p,
                "selected": s,
            })

    changes = 0
    for pkg in selected:
        if prior.get(pkg) != selected[pkg]:
            changes += 1
    for pkg in prior:
        if pkg not in selected:
            changes += 1

    freshness = 0
    for pkg in selected:
        v = selected[pkg]
        freshness += 100 * v[0] + 10 * v[1] + v[2]

    return {
        "active_dependencies": active_dependencies,
        "prior_deltas": prior_deltas,
        "score": {"changes": changes, "freshness": freshness},
    }
"}

{"packages/analysis/global_selection.py": "def select_versions(request, roots, assess):
    """Enumerate every distinct feasible complete assignment exactly once and
    return the one minimizing changes and then maximizing freshness.

    request: public request with config (roots, features, prior) and catalog.
    roots: any subset of the original root request rows (with original intervals).
    assess: callable assess(roots, selected) -> evaluation dict or None.
    """
    config = request["config"]
    features = set(config.get("features", []))
    catalog = request["catalog"]

    packages = [c["package"] for c in catalog]
    versions_by_pkg = {}
    deps_by_version = {}
    for c in catalog:
        pkg = c["package"]
        vs = []
        for entry in c["versions"]:
            v = tuple(entry["version"])
            vs.append(v)
            deps_by_version[(pkg, v)] = entry["deps"]
        versions_by_pkg[pkg] = vs

    root_pkgs = set(r["package"] for r in roots)
    root_intervals = {r["package"]: (r["min"], r["max"]) for r in roots}

    def is_active(dep):
        return dep["kind"] == "required" and (
            dep["feature"] is None or dep["feature"] in features
        )

    def req_targets(pkg, v):
        return [d["package"] for d in deps_by_version[(pkg, v)] if is_active(d)]

    # Static over-approximation of the required closure: an edge p -> q exists
    # when some offered version of p has an active required dependency on q.
    graph = {p: set() for p in packages}
    for p in packages:
        for v in versions_by_pkg[p]:
            for t in req_targets(p, v):
                graph[p].add(t)
    reachable = set()
    stack = list(root_pkgs)
    while stack:
        p = stack.pop()
        if p in reachable:
            continue
        reachable.add(p)
        for t in graph[p]:
            if t not in reachable:
                stack.append(t)

    def in_interval(v, mn, mx):
        if mn is not None and tuple(mn) > v:
            return False
        if mx is not None and v >= tuple(mx):
            return False
        return True

    feasible_count = 0
    best = None  # (key, chosen, evaluation)

    selected = {}  # pkg -> version tuple, or None for unselected

    def dfs(i, must):
        nonlocal feasible_count, best
        if i == len(packages):
            chosen = {p: list(v) for p, v in selected.items() if v is not None}
            evaluation = assess(roots, chosen)
            if evaluation is not None:
                feasible_count += 1
                score = evaluation["score"]
                key = (score["changes"], -score["freshness"])
                if best is None or key < best[0]:
                    best = (key, chosen, evaluation)
            return

        pkg = packages[i]
        if pkg in must:
            for v in versions_by_pkg[pkg]:
                if pkg in root_intervals:
                    mn, mx = root_intervals[pkg]
                    if not in_interval(v, mn, mx):
                        continue
                targets = req_targets(pkg, v)
                conflict = any(
                    t in selected and selected[t] is None for t in targets
                )
                if conflict:
                    continue
                selected[pkg] = v
                dfs(i + 1, must | set(targets))
                del selected[pkg]
        else:
            # Leave unselected.
            selected[pkg] = None
            dfs(i + 1, must)
            del selected[pkg]
            # Select only if it can possibly belong to the required closure.
            if pkg in reachable:
                for v in versions_by_pkg[pkg]:
                    if pkg in root_intervals:
                        mn, mx = root_intervals[pkg]
                        if not in_interval(v, mn, mx):
                            continue
                    targets = req_targets(pkg, v)
                    conflict = any(
                        t in selected and selected[t] is None for t in targets
                    )
                    if conflict:
                        continue
                    selected[pkg] = v
                    dfs(i + 1, must | set(targets))
                    del selected[pkg]

    dfs(0, set(root_pkgs))

    if feasible_count == 0:
        return {"feasible_count": 0, "selected": {}, "evaluation": None}

    _, chosen, evaluation = best
    return {
        "feasible_count": feasible_count,
        "selected": chosen,
        "evaluation": evaluation,
    }
"}

