    prior = config.get("prior", {})

    catalog = {}
    for entry in request["catalog"]:
        versions = {}
        for v in entry["versions"]:
            versions[tuple(v["version"])] = v
        catalog[entry["package"]] = versions

    # Validate selected mapping: every selected package must exist in the
    # catalog and its version must be an offered version.
    for pkg, version in selected.items():
        if pkg not in catalog:
            return None
        if tuple(version) not in catalog[pkg]:
            return None

    # Every root must be selected within its interval.
    for root in roots:
        pkg = root["package"]
        if pkg not in selected:
            return None
        if not _in_interval(selected[pkg], root.get("min"), root.get("max")):
            return None

    # Compute the required closure starting from roots.
    closure = set()
    stack = [root["package"] for root in roots]
    while stack:
        pkg = stack.pop()
        if pkg in closure:
            continue
        closure.add(pkg)
        version = selected[pkg]
        entry = catalog[pkg][tuple(version)]
        for dep in entry["deps"]:
            if dep["kind"] == "required" and _active(dep, features):
                target = dep["package"]
                if target not in selected:
                    return None
                if not _in_interval(selected[target], dep.get("min"), dep.get("max")):
                    return None
                if target not in closure:
                    stack.append(target)

    # No package outside the required closure may be selected.
    for pkg in selected:
        if pkg not in closure:
            return None

    # Peer dependencies: target must already be in the required closure and
    # satisfy the peer interval.
    active_dependencies = []
    for pkg in closure:
        version = selected[pkg]
        entry = catalog[pkg][tuple(version)]
        for dep in entry["deps"]:
            if not _active(dep, features):
                continue
            target = dep["package"]
            if dep["kind"] == "peer":
                if target not in closure:
                    return None
                if not _in_interval(selected[target], dep.get("min"), dep.get("max")):
                    return None
            active_dependencies.append({
                "source": pkg,
                "target": target,
                "kind": dep["kind"],
                "feature": dep.get("feature"),
            })

    # prior_deltas: union of prior and selected keys where they differ.
    prior_deltas = []
    all_keys = set(prior) | set(selected)
    for pkg in all_keys:
        p = prior.get(pkg)
        s = selected.get(pkg)
        if p != s:
            prior_deltas.append({
                "package": pkg,
                "prior": p,
                "selected": s,
            })

    changes = 0
    for pkg in selected:
        if prior.get(pkg) != selected[pkg]:
            changes += 1
    for pkg in prior:
        if pkg not in selected:
            changes += 1

    freshness = 0
    for pkg in selected:
        v = selected[pkg]
        freshness += 100 * v[0] + 10 * v[1] + v[2]

    return {
        "active_dependencies": active_dependencies,
        "prior_deltas": prior_deltas,
        "score": {"changes": changes, "freshness": freshness},
    }
