        }

    return {
        "status": "blocked",
        "selected": [],
        "active_dependencies": [],
        "prior_deltas": [],
        "score": None,
        "feasible_count": 0,
        "minimal_root_conflict": _minimal_root_conflict(request, roots),
    }


