def _version_key(v):
    return tuple(v)


def _in_interval(version, min_v, max_v):
    if min_v is not None and _version_key(version) < _version_key(min_v):
        return False
    if max_v is not None and _version_key(version) >= _version_key(max_v):
        return False
    return True


def _active(dep, features):
    return dep.get("feature") is None or dep.get("feature") in features


def assess_selection(request, roots, selected):
    config = request["config"]
    features = set(config.get("features", []))
    prior = config.get("prior", {})

    catalog = {}
    for entry in request["catalog"]:
        versions = {}
        for v in entry["versions"]:
            versions[tuple(v["version"])] = v
        catalog[entry["package"]] = versions

