    graph = {p: set() for p in packages}
    for p in packages:
        for v in versions_by_pkg[p]:
            for t in req_targets(p, v):
                graph[p].add(t)
    reachable = set()
    stack = list(root_pkgs)
    while stack:
        p = stack.pop()
        if p in reachable:
            continue
        reachable.add(p)
        for t in graph[p]:
            if t not in reachable:
                stack.append(t)

    def in_interval(v, mn, mx):
        if mn is not None and tuple(mn) > v:
            return False
        if mx is not None and v >= tuple(mx):
            return False
        return True

    feasible_count = 0
    best = None  # (key, chosen, evaluation)

    selected = {}  # pkg -> version tuple, or None for unselected

    def dfs(i, must):
        nonlocal feasible_count, best
        if i == len(packages):
            chosen = {p: list(v) for p, v in selected.items() if v is not None}
            evaluation = assess(request, roots, chosen)
            if evaluation is not None:
                feasible_count += 1
                score = evaluation["score"]
                key = (score["changes"], -score["freshness"])
                if best is None or key < best[0]:
                    best = (key, chosen, evaluation)
            return

        pkg = packages[i]
        if pkg in must:
            for v in versions_by_pkg[pkg]:
                if pkg in root_intervals:
                    mn, mx = root_intervals[pkg]
                    if not in_interval(v, mn, mx):
                        continue
                targets = req_targets(pkg, v)
                conflict = any(
                    t in selected and selected[t] is None for t in targets
                )
                if conflict:
                    continue
                selected[pkg] = v
                dfs(i + 1, must | set(targets))
                del selected[pkg]
        else:
            # Leave unselected.
            selected[pkg] = None
            dfs(i + 1, must)
            del selected[pkg]
            # Select only if it can possibly belong to the required closure.
            if pkg in reachable:
                for v in versions_by_pkg[pkg]:
                    if pkg in root_intervals:
                        mn, mx = root_intervals[pkg]
                        if not in_interval(v, mn, mx):
                            continue
                    targets = req_targets(pkg, v)
                    conflict = any(
                        t in selected and selected[t] is None for t in targets
                    )
                    if conflict:
                        continue
                    selected[pkg] = v
                    dfs(i + 1, must | set(targets))
                    del selected[pkg]

    dfs(0, set(root_pkgs))

    if feasible_count == 0:
        return {"feasible_count": 0, "selected": {}, "evaluation": None}

    _, chosen, evaluation = best
    return {
        "feasible_count": feasible_count,
        "selected": chosen,
        "evaluation": evaluation,
    }

import unittest


SPEC = "packages/analysis/SPEC.md"

API_BOUNDARY_REQUIREMENTS = [
    {
        "target_path": "packages/analysis/engine.py",
        "function": "transform",
        "rules": {
            "nonfinite_unknown_field": {
                "applicable": False,
                "contract_path": SPEC,
                "requirement_quote": "All inputs are valid finite data; no malformed-input rejection",
                "reason": "SPEC explicitly states all inputs are valid finite data and no malformed-input rejection is required.",
            },
            "invalid_payload_type": {
                "applicable": False,
                "contract_path": SPEC,
                "requirement_quote": "All inputs are valid finite data; no malformed-input rejection",
                "reason": "SPEC states inputs are valid finite data; no malformed-input rejection is required.",
            },
        },
    },
]


def _request():
    return {
        "config": {
            "roots": [{"package": "A", "min": None, "max": None}],
            "features": [],
            "prior": {},
        },
        "catalog": [
            {
                "package": "A",
                "versions": [
                    {"version": [1, 0, 0], "deps": []},
                    {"version": [2, 0, 0], "deps": []},
                    {"version": [3, 0, 0], "deps": []},
                ],
            }
        ],
    }


class TransformBehaviorTests(unittest.TestCase):
    def test_ready_report_shape_and_optimal_selection(self):
        # SPEC: minimize changes then maximize freshness; prior empty so all
        # versions tie on changes=1, freshness favors [3,0,0].
        payload = {"request": _request()}
        result = call_candidate("packages/analysis/engine.py", "transform",
                                args=[payload, {}])
        self.assertEqual(result["status"], "ready")
        self.assertEqual(result["feasible_count"], 3)
        self.assertEqual(result["minimal_root_conflict"], [])
        self.assertEqual(result["score"]["changes"], 1)
        self.assertEqual(result["score"]["freshness"], 300)
        self.assertEqual(result["selected"], [{"package": "A", "version": [3, 0, 0]}])

    def test_prior_lock_minimizes_changes(self):
        # SPEC: prior A=[1,0,0] means version 1 has changes=0 and wins despite
        # lower freshness than version 3.
        req = _request()
        req["config"]["prior"] = {"A": [1, 0, 0]}
        result = call_candidate("packages/analysis/engine.py", "transform",
                                args=[{"request": req}, {}])
        self.assertEqual(result["selected"], [{"package": "A", "version": [1, 0, 0]}])
        self.assertEqual(result["score"]["changes"], 0)
        self.assertEqual(result["score"]["freshness"], 100)
        self.assertEqual(result["prior_deltas"], [])

    def test_blocked_conflict_reports_minimal_root_conflict(self):
        # Two roots A and B each require incompatible C versions; the pair is
        # the minimum infeasible subset.
        req = {
            "config": {
                "roots": [
                    {"package": "A", "min": None, "max": None},
                    {"package": "B", "min": None, "max": None},
                ],
                "features": [],
                "prior": {},
            },
            "catalog": [
                {"package": "A", "versions": [
                    {"version": [1, 0, 0], "deps": [
                        {"package": "C", "min": [1, 0, 0], "max": [2, 0, 0],
                         "kind": "required", "feature": None}]}]},
                {"package": "B", "versions": [
                    {"version": [1, 0, 0], "deps": [
                        {"package": "C", "min": [2, 0, 0], "max": [3, 0, 0],
                         "kind": "required", "feature": None}]}]},
                {"package": "C", "versions": [
                    {"version": [1, 0, 0], "deps": []},
                    {"version": [2, 0, 0], "deps": []}]},
            ],
        }
        result = call_candidate("packages/analysis/engine.py", "transform",
                                args=[{"request": req}, {}])
        self.assertEqual(result["status"], "blocked")
        self.assertEqual(result["selected"], [])
        self.assertEqual(result["score"], None)
        self.assertEqual(result["feasible_count"], 0)
        self.assertEqual(sorted(result["minimal_root_conflict"]), ["A", "B"])

    def test_peer_does_not_pull_target_into_closure(self):
        # SPEC: a peer does not pull its target into the required closure.
        req = {
            "config": {
                "roots": [{"package": "A", "min": None, "max": None}],
                "features": ["turbo"],
                "prior": {},
            },
            "catalog": [
                {"package": "A", "versions": [
                    {"version": [1, 0, 0], "deps": [
                        {"package": "B", "min": None, "max": None,
                         "kind": "peer", "feature": "turbo"}]}]},
                {"package": "B", "versions": [
                    {"version": [1, 0, 0], "deps": []}]},
            ],
        }
        result = call_candidate("packages/analysis/engine.py", "transform",
                                args=[{"request": req}, {}])
        # A alone is invalid (peer target B not in closure); B not rooted, so
        # the whole request is blocked.
        self.assertEqual(result["status"], "blocked")
        self.assertEqual(result["feasible_count"], 0)


